/* SHADES studio: a curved rail, continuous rack position, and layered front/back art. */
window.initShadesHero=function(){
const old=document.querySelector('.hero');if(!old)return;
const pieces=P.slice(0,6),N=pieces.length;
old.outerHTML=`<section class="motion-hero" aria-label="SHADES interactive clothing studio"><div class="studio-heading"><span class="eyebrow">THE SHADES STUDIO · COIMBATORE</span><h1>Designed for Motion.<br><em>Built for Presence.</em></h1><p>Contemporary menswear engineered for the way you move.</p><div class="studio-actions"><a class="button dark" href="shop.html">Explore collection</a><a class="text-link" href="lookbook.html">View lookbook</a></div></div><div class="studio-scene" id="studio-scene" role="region" tabindex="0" aria-label="Hanging menswear. Drag horizontally, use arrow keys, or select a garment." aria-describedby="studio-help"><div class="studio-light" aria-hidden="true"></div><div class="studio-world" id="studio-world"><svg class="studio-rail" viewBox="0 0 1440 180" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="rail-metal" x2="0" y2="1"><stop stop-color="#b2a488"/><stop offset=".4" stop-color="#f1eadb"/><stop offset=".65" stop-color="#8d826b"/><stop offset="1" stop-color="#c5b99c"/></linearGradient></defs><path d="M-120 25 Q720 230 1560 25" fill="none" stroke="url(#rail-metal)" stroke-width="4"/><path d="M-120 29 Q720 234 1560 29" fill="none" stroke="#233323" stroke-opacity=".08" stroke-width="2"/></svg>${pieces.map((p,i)=>`<button class="studio-piece" data-studio-piece="${i}" aria-label="Select ${p.name}" aria-pressed="${i===0}" style="--piece:${i}"><span class="studio-cord" aria-hidden="true"></span><span class="studio-sway">${solid(p)}</span><span class="studio-floor-shadow" aria-hidden="true"></span></button>`).join('')}</div><span class="studio-scene-label" aria-hidden="true">FORM. TEXTURE. PRESENCE.</span></div><div class="studio-bottom"><div class="studio-cue"><span class="eyebrow">A WARDROBE, IN PERSPECTIVE</span><p id="studio-help">Drag the rail. Hover or tap a piece.</p><a href="#new-perspectives" class="studio-scroll">Scroll to discover <span aria-hidden="true"></span></a></div><div class="studio-product" id="studio-product" aria-live="polite"></div><div class="studio-navigation"><button id="studio-prev" aria-label="Previous garment"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg></button><span id="studio-position">01 / 06</span><button id="studio-next" aria-label="Next garment"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m10 6 6 6-6 6"/></svg></button></div></div></section>`;
const hero=document.querySelector('.motion-hero'),scene=document.querySelector('#studio-scene'),world=document.querySelector('#studio-world'),buttons=[...document.querySelectorAll('[data-studio-piece]')],panel=document.querySelector('#studio-product'),counter=document.querySelector('#studio-position');
document.querySelector('.home-products')?.closest('section')?.setAttribute('id','new-perspectives');
const wrap=n=>((n%N)+N)%N,reduce=matchMedia('(prefers-reduced-motion: reduce)');
let active=-1,back=false,position=0,target=0,raf=0,last=0,drag=null,pointer={x:0,y:0},visible=true;
function details(index){if(index===active)return;active=index;back=false;const p=pieces[index];buttons.forEach((b,i)=>{b.classList.toggle('is-selected',i===index);b.classList.remove('is-back');b.setAttribute('aria-pressed',String(i===index))});counter.textContent=String(index+1).padStart(2,'0')+' / 06';panel.innerHTML=`<div class="studio-product-copy"><span class="eyebrow">${p.category} / ${p.color}</span><h2>${p.name}</h2><p>${p.fit} fit · ${p.fabric} · ${p.sizes[0]}–${p.sizes.at(-1)}</p></div><div class="studio-product-buy"><strong>${money(p.price)}</strong><button id="studio-turn" aria-label="Show back of ${p.name}">Show back</button><a href="${url(p)}" class="button dark">View product</a></div>`;document.querySelector('#studio-turn').onclick=()=>{back=!back;buttons[index].classList.toggle('is-back',back);const b=document.querySelector('#studio-turn');b.textContent=back?'Show front':'Show back';b.setAttribute('aria-label',`Show ${back?'front':'back'} of ${p.name}`)};}
function paint(){const width=scene.clientWidth,height=scene.clientHeight,mobile=width<761,step=mobile?145:Math.min(205,width*.147),garmentHeight=mobile?340:Math.min(460,height*.98),garmentWidth=garmentHeight/2;
 buttons.forEach((b,i)=>{let d=wrap(i-position+3)-3;const distance=Math.abs(d),x=width/2+d*step,curve=62-Math.pow((x-width/2)/(width/2),2)*54;const scale=1-Math.min(distance,3)*.055;const focus=Math.max(0,1-distance);b.style.width=garmentWidth+'px';b.style.height=garmentHeight+'px';b.style.transform=`translate3d(${x-garmentWidth/2}px,${curve-focus*22}px,${focus*110}px) scale(${scale})`;b.style.zIndex=20-Math.round(distance*3);b.style.opacity=String(.48+focus*.52);b.style.setProperty('--yaw',(distance<.01?0:(d>0?-1:1)*Math.min(74,46+distance*10))+'deg');b.style.setProperty('--cord-top',(-curve)+'px');b.style.filter=distance>1.6?'blur(.4px)':'none';});
 const selected=wrap(Math.round(position));details(selected);world.style.setProperty('--parallax-x',pointer.x+'px');world.style.setProperty('--parallax-y',pointer.y+'px');}
function frame(now){raf=0;const dt=last?Math.min(now-last,50):16;last=now;position=reduce.matches?target:position+(target-position)*(1-Math.exp(-dt*.008));if(Math.abs(position-target)<.0005)position=target;paint();if(position!==target&&visible)raf=requestAnimationFrame(frame);else last=0;}
function wake(){if(!raf&&visible)raf=requestAnimationFrame(frame)}
function select(index){const current=wrap(Math.round(target));let delta=index-current;if(delta>3)delta-=N;if(delta< -3)delta+=N;target=Math.round(target)+delta;wake()}
function move(n){target=Math.round(target)+n;wake()}
buttons.forEach((b,i)=>{b.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'&&!drag&&Math.abs(position-target)<.02)select(i)});b.addEventListener('focus',()=>select(i));b.addEventListener('click',()=>{if(!hero.classList.contains('was-dragged'))select(i)})});
document.querySelector('#studio-prev').onclick=()=>move(-1);document.querySelector('#studio-next').onclick=()=>move(1);
scene.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End','Escape'].includes(e.key)){e.preventDefault();if(e.key==='Escape'){back=false;buttons[active].classList.remove('is-back');document.querySelector('#studio-turn').textContent='Show back'}else if(e.key==='Home')select(0);else if(e.key==='End')select(N-1);else move(e.key==='ArrowRight'?1:-1)}});
scene.addEventListener('pointerdown',e=>{if(e.button!==0)return;if(e.pointerType==='mouse')e.preventDefault();hero.classList.remove('was-dragged');drag={id:e.pointerId,x:e.clientX,start:target,moved:0};});
scene.addEventListener('pointermove',e=>{if(drag){const dx=e.clientX-drag.x;drag.moved=Math.max(drag.moved,Math.abs(dx));if(drag.moved>7){scene.setPointerCapture(e.pointerId);hero.classList.add('is-dragging','was-dragged');target=drag.start-dx/(scene.clientWidth<761?145:195);wake()}}else if(e.pointerType==='mouse'&&!reduce.matches){const r=scene.getBoundingClientRect();pointer.x=(e.clientX-r.left-r.width/2)*.008;pointer.y=(e.clientY-r.top-r.height/2)*.008;wake()}});
function release(){if(!drag)return;drag=null;target=Math.round(target);hero.classList.remove('is-dragging');wake();setTimeout(()=>hero.classList.remove('was-dragged'),0)}
window.addEventListener('pointerup',release);scene.addEventListener('pointercancel',release);scene.addEventListener('lostpointercapture',release);scene.addEventListener('pointerleave',()=>{pointer={x:0,y:0};if(!drag)wake()});
new MutationObserver(()=>{buttons.forEach(b=>{b.tabIndex=b.getAttribute('aria-pressed')==='true'?0:-1})}).observe(world,{subtree:true,attributes:true,attributeFilter:['aria-pressed']});
new ResizeObserver(paint).observe(scene);reduce.addEventListener('change',()=>{pointer={x:0,y:0};wake()});new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;hero.classList.toggle('studio-paused',!visible);if(visible)wake()},{threshold:0}).observe(hero);paint();buttons.forEach((b,i)=>b.tabIndex=i===0?0:-1);
};
